/*
 * Embed the LVGL binary UI fonts (generated by lv_font_conv, committed under
 * openrtx/fonts/) directly into flash via .incbin, one blob per fontSize_t.
 * The paths resolve relative to the build directory (a sibling of the repo
 * root, matching voicePromptData.S). Phase 1 embeds the 1bpp (aliased) set for
 * every target; a later phase selects a 4bpp anti-aliased set for colour
 * displays via CONFIG_PIX_FMT_*.
 */

.section .note.GNU-stack,""
.section .rodata

.macro FONT_BLOB name, path
.global _font_\name\()_start
.global _font_\name\()_end
_font_\name\()_start:
    .incbin "\path"
.set _font_\name\()_end, .
.endm

FONT_BLOB 5,  "../openrtx/fonts/ubuntu_5_1.bin"
FONT_BLOB 6,  "../openrtx/fonts/ubuntu_6_1.bin"
FONT_BLOB 8,  "../openrtx/fonts/ubuntu_8_1.bin"
FONT_BLOB 9,  "../openrtx/fonts/ubuntu_9_1.bin"
FONT_BLOB 10, "../openrtx/fonts/ubuntu_10_1.bin"
FONT_BLOB 12, "../openrtx/fonts/ubuntu_12_1.bin"
FONT_BLOB 16, "../openrtx/fonts/ubuntu_16_1.bin"
